import java.util.*; public class TypingAccuracyChecker{static void checkTypingAccuracy(String o,String t){int n=Math.min(o.length(),t.length()),m=0,f=-1;for(int i=0;i<n;i++)if(o.charAt(i)==t.charAt(i))m++;else if(f<0)f=i;double p=m*100.0/Math.max(o.length(),t.length());System.out.printf("Matched: %d/%d | Accuracy: %.2f%%%n",m,Math.max(o.length(),t.length()),p);if(f<0&&o.length()==t.length())System.out.println("No Mismatches");else if(f>=0)System.out.println("First Mismatch at position "+(f+1));}public static void main(String[] z){Scanner s=new Scanner(System.in);checkTypingAccuracy(s.nextLine(),s.nextLine());}}